"""Honest geometry/animation/progression coverage of the explicit local assets."""
import hashlib,json,pathlib,zipfile
from extract_ee2_models import ROOT,OUT,INSTALL
from import_ee2_units import Database

def run():
 manifest_path=OUT/'models/manifest.json';manifest=json.loads(manifest_path.read_text(encoding='utf8'));units=json.loads((ROOT/'docs/ee2-units.json').read_text(encoding='utf8'))
 rows=manifest['models'];files={r['url']:json.loads((ROOT/'docs'/r['url']).read_text(encoding='utf8'))for r in rows};aliases=[r for r in rows if 'progressionBinding'in r]
 with zipfile.ZipFile(INSTALL/'zips/graphics.zip')as z:
  names=z.namelist();nifs=[n for n in names if n.casefold().endswith('.nifcache')];kfs=[n for n in names if n.casefold().endswith('.kf')]
  cultures={base:[pathlib.PurePosixPath(n).stem for n in nifs if pathlib.PurePosixPath(n).stem.casefold().startswith(base.casefold())]for base in ['bld_citycenter1_','LSF1_citizen_','lhi1_maceman_']}
  static=[]
  for url,data in files.items():
   if data['normalization']['kind']not in ['human','vehicle']or data.get('animationSources'):continue
   stem=pathlib.PurePosixPath(data['source']['entry']).stem.casefold();matching=[n for n in kfs if pathlib.PurePosixPath(n).name.casefold().startswith(stem+'_')]
   static.append({'url':url,'source':data['source'],'boundDefinitions':sorted({r['id']for r in rows if r['url']==url}),'matchingNativeKFs':matching,'limitation':'Static original geometry. Native KF not yet bound.'if matching else'Static original geometry. No matching external KF found by exact source stem; native procedural/controller motion remains unaudited.'})
 matrix=[]
 for native in units['class_rows']:
  identifier=native['id'];candidates=[r for r in rows if r['id']==identifier and r['epoch']<=native['epoch']];selected=max(candidates,key=lambda r:r['epoch'])if candidates else None;proof=selected.get('progressionBinding')if selected else None
  explicit=bool(proof and (proof['sourceUnit'],proof['sourceVisual'])==(native['source_unit'],native['source_visual'])and proof['epoch']<=native['epoch']<proof['until'])
  verified=bool(native['model_verified']or explicit)
  matrix.append({'id':identifier,'epoch':native['epoch'],'until':native['until'],'sourceUnit':native['source_unit'],'sourceVisual':native['source_visual'],'legacyModelFlag':native['model_verified'],'renderVisualVerified':verified,'verifiedBy':'identical-native-class-visual-alias'if explicit else'previous-strict-model-evidence'if verified else'none: renderer fallback remains','renderedUrl':selected['url']if selected else None,'renderedBindingEpoch':selected['epoch']if selected else None,'upgradeSource':native['upgrade_source']})
 db=Database(INSTALL/'zips/db.zip')
 try:
  upgrades=db.table('db/TechTree/upgrade_unittypes.csv');declared_types=sum(v['kind']=='UnitType'for v in db.blocks.values());native_classes=len({r['UNIT']for r in upgrades if r.get('CIV','All')=='All'})
 finally:db.close()
 checks={name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest()for name in ['tools/test_ee2_models.py','tools/test_ee2_citizen_poses.py','tools/test_ee2_aircraft_poses.py','tools/test_ee2_epoch_visuals.py','tools/test_ee2_future_motion.py','tools/original-models-test.mjs']}
 result={'format':'ee2-original-model-coverage-v1','scope':'Actual imported source geometry, native KF samples and renderer epoch bindings only. Not a claim that the whole EE2 game, playable roster, civilizations or assets are complete. Base db.zip only; no patch precedence inferred.',
  'manifestSha256':hashlib.sha256(manifest_path.read_bytes()).hexdigest(),
  'sourceAssets':{'nif':[{'url':url,**data['source']}for url,data in sorted(files.items())],'kf':list({a['entry']:{'archive':'graphics.zip',**a}for data in files.values()for a in data.get('animationSources',[])}.values()),'improvedMotionBindings':[{'id':r['id'],'url':r['url'],'source':files[r['url']]['source'],'animationSources':files[r['url']].get('animationSources',[]),'databaseBinding':files[r['url']].get('nativeMotionBinding')or files[r['url']].get('aircraftVisualBinding')}for r in rows if r['id']in[37,38,41,43,46]and'progressionBinding'not in r]},
  'counts':{'definitionRoles':len({r['id']for r in rows if r['id']<100}),'propRoles':len({r['id']for r in rows if r['id']>=100}),'rendererBindings':len(rows),'uniqueImportedNIFs':len(files),'nativeFarMeshes':len({r['lodFarUrl']for r in rows if r.get('lodFarUrl')}),'geometryFilesWithKFClips':sum(bool(f.get('animationSources'))for f in files.values()),'distinctBoundKFEntries':len({a['entry']for f in files.values()for a in f.get('animationSources',[])}),'stillStaticMobileMeshes':len(static),'staticMobileMeshesWithExactStemNativeKFs':sum(bool(r['matchingNativeKFs'])for r in static),'nativeClassEpochRows':len(matrix),'verifiedClassEpochVisualRows':sum(r['renderVisualVerified']for r in matrix),'unverifiedClassEpochVisualRows':sum(not r['renderVisualVerified']for r in matrix),'newLaterEpochBindings':len(aliases),'newExistingExactSpriteBindings':len(manifest.get('epochIconBindings',[])),'archiveNIFEntries':len(nifs),'archiveKFEntries':len(kfs),'baseDeclaredUnitTypeNamesIncludingHelpers':declared_types,'baseUpgradeTableAllCivUnitClasses':native_classes,'distinctBoundSourceUnitClasses':len({r['source_unit']for r in units['bindings']})},
  'upgradesDelivered':[{'id':i,'kind':'native rotor/propeller and aircraft states','clips':['idle','walk','combat'],'sourceFrames':48}for i in [37,38,41]]+[{'id':43,'kind':'Existing native Mech gait refined from 8 to 24 source samples','clips':['idle','walk','combat'],'sourceFrames':24},{'id':46,'kind':'Native declared Idle/Walk with 48 samples; seven wheel groups move, track UV controller is explicitly unsupported','clips':['idle','walk'],'sourceFrames':48}],'futurePriorityFindings':json.loads((OUT/'models/future-priority-findings.json').read_text(encoding='utf8')),'epochBindings':[{'id':r['id'],'epoch':r['epoch'],'until':r['nativeUntil'],'url':r['url'],'proof':r['progressionBinding']}for r in aliases],
  'classEpochVisualAudit':matrix,'staticMobileModels':static,'nativeCultureAndGenderExamples':cultures,
  'openParts':['Only the current 57 adapted definition roles are represented; original declared helper/unit types and upgrade classes are not a fully playable original roster.','Missing source visuals in the complete native class progression remain explicit renderer fallbacks. An original mesh in a different era is not claimed as the native appearance of the missing era.','Western cache variants dominate; the other native cultural sets and female citizen geometry are not generally selectable or bound.','Native deaths, takeoff/landing, animation variants, text-key events, particle children, billboard/controller systems and complete material/rendering parity are not implemented by this geometry export.','The morph exporter samples real KF tracks, but its linear/slerp interpolation does not reproduce all native quadratic tangents or event timing.','Existing native far LODs are used only when present and lower in triangle count; no procedural reduction is substituted.'],
  'validation':{'parserAndLODTests':6,'citizenPoseTests':4,'aircraftSourceAndPhysicsTests':4,'epochBindingTests':5,'futureMotionTests':4,'unitImportTests':15,'originalModelsNodeAudit':'Passed after the new exports and bindings; includes source hashes, mesh buffers, PNGs, normalization, far LOD and clip schema.','sourceTestFiles':checks,'runtimeNumbers':'Fortress ID56 adds seven native stat stages and garrison metadata; pre-existing field values of IDs0..55 remain identical to the previous dataset. No byte-equivalent Rust or WASM claim.','unitImportProof':json.loads((OUT/'models/unit-import-validation.json').read_text(encoding='utf8'))}}
 (OUT/'models/coverage-audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
 c=result['counts'];text=f"Originalgrafik: tatsaechlicher Stand\n\n{c['rendererBindings']} Modell-/Epochenbindungen fuer {c['definitionRoles']} vorhandene Spielrollen und {c['propRoles']} Landschaftsrollen; {c['uniqueImportedNIFs']} verschiedene Original-NIF-Dateien und {c['nativeFarMeshes']} echte Fernmodelle.\n{c['geometryFilesWithKFClips']} Modelle mit originalen KF-Clips. Neu: Propeller/Hubschrauberrotoren fuer drei Flugmodelle mit 48 statt 8 Samples; Mech-Gang mit 24 statt 8 Samples; Myrmidon-Radgruppen mit nativen Idle/Walk-Clips. Konstante Teile bleiben kompakt. Zukunftsflugzeug44 hat nur konstante native KF-Posen; bei Manta45 fehlt eine passende externe KF-Datei. Dort wird keine Bewegung erfunden.\n{c['newLaterEpochBindings']} belegte spaetere Epochenbindungen verwenden vorhandene identische Originalklassen/-visuals, dazu {c['newExistingExactSpriteBindings']} passende quellenbelegte Original-Icons.\n\nNicht fertig:\n{c['unverifiedClassEpochVisualRows']} von {c['nativeClassEpochRows']} Klassen-/Epochenzeilen besitzen weiterhin keinen vollstaendig belegten nativen visuellen Wechsel. {c['stillStaticMobileMeshes']} mobile Modelle sind noch statisch exportiert; bei {c['staticMobileMeshesWithExactStemNativeKFs']} davon liegen passende externe KF-Dateien vor. Weitere Kulturen, weibliche Buerger, Todes-/Start-/Landeanimationen, Effekte und vollstaendige Originaldarstellung fehlen.\n\nDie Installation enthaelt {c['archiveNIFEntries']} NIF-Caches und {c['archiveKFEntries']} KF-Dateien. Diese Dateizahlen sind KEIN Vollstaendigkeitsprozentsatz des Spiels: darunter sind Varianten und Effekte. Das Spiel ist weiterhin ein Ausbau mit Originalassets, kein vollstaendig nachgebautes Empire Earth II.\n\nAlle Einzelquellen, offenen Epochen, Bindungen und Testnachweise stehen in coverage-audit.json. Festung56 ergaenzt sieben belegte Quellenstufen. Die bisherigen Werte aller vorhandenen Felder fuer IDs0..55 sind unveraendert; die erzeugte Rust-Tabelle wurde bewusst erweitert. Ein erforderlicher Engine-/WASM-Neubau wird getrennt geprueft.\n"
 (OUT/'models/coverage-audit.txt').write_text(text,encoding='utf8')
 research=ROOT.parent/'EE2-Research/analysis';research.mkdir(parents=True,exist_ok=True)
 (research/'graphics-coverage.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
 (research/'graphics-coverage.txt').write_text(text,encoding='utf8');print(c)
 return result
if __name__=='__main__':run()
